#define main joint_program_main
#include "joint.cpp"
#undef main
#include <gtsam/slam/PriorFactor.h>
int main(int argc,char**argv){try{json tests=unit();
 std::vector<Vector4>p;for(int i=0;i<15;i++)p.emplace_back(i*2.+.25,(i%3)*3.+.2,(i%4)*2.+.4,1.);auto c=std::make_shared<Cloud>(p);std::vector<Matrix4> cov(p.size(),Matrix4::Zero());for(auto&a:cov)a.topLeftCorner<3,3>()=.2*Matrix3::Identity();c->add_covs(cov);auto vm=vox(c);auto native=boost::make_shared<GP>(Pose3(),X(0),vm,c);auto robust=boost::make_shared<Geometry>(native,.05,c,vm);Values z;Pose3 pose(Rot3::RzRyRx(.001,-.001,.001),Vector3(.02,.01,.02));z.insert(X(0),pose);auto h=boost::dynamic_pointer_cast<HessianFactor>(robust->linearize(z));Matrix A=h->augmentedInformation();Vector fd(6);for(int j=0;j<6;j++){Vector6 d=Vector6::Zero();d(j)=1e-7;Values a=z,b=z;a.update(X(0),pose.retract(d));b.update(X(0),pose.retract(-d));fd(j)=(robust->error(a)-robust->error(b))/2e-7;}tests["Huber_fixed_cache_gradient_max"]=(fd+A.topRightCorner(6,1)).cwiseAbs().maxCoeff();double before=robust->error(z);auto clone=robust->clone();Values other=z;other.update(X(0),Pose3(Rot3::Rz(.2),Vector3(4,4,4)));clone->linearize(other);tests["deep_clone_cost_interference"]=std::abs(before-robust->error(z));
 LevenbergMarquardtParams lm;lm.maxIterations=8;lm.absoluteErrorTol=1e-10;lm.relativeErrorTol=1e-10;NativeFixedLag lag(.5,lm,true);NonlinearFactorGraph all;Values batchinit;for(int i=0;i<3;i++){NonlinearFactorGraph add;Values val;val.insert(V(i),Vector3(4.,-3.,2.));batchinit.insert(V(i),Vector3(4.,-3.,2.));if(i==0)add.push_back(boost::make_shared<PriorFactor<Vector3>>(V(i),Vector3::Zero(),noiseModel::Isotropic::Sigma(3,.1)));else add.push_back(boost::make_shared<BetweenFactor<Vector3>>(V(i-1),V(i),Vector3(.2,-.1,.05),noiseModel::Isotropic::Sigma(3,.2)));all.push_back(add);lag.update(add,val,{{V(i),i*.3}});}auto estimate=lag.calculateEstimate();gtsam_points::LevenbergMarquardtExtParams pp;pp.maxIterations=8;gtsam_points::LevenbergMarquardtOptimizerExt batch(all,batchinit,pp);auto be=batch.optimize();tests["marginal_mean_vs_batch_max"]=(estimate.at<Vector3>(V(2))-be.at<Vector3>(V(2))).cwiseAbs().maxCoeff();auto copy=diagnosticCopy(lag.getFactors());Marginals marginal(copy,estimate);tests["marginal_P_vs_analytic_max"]=(marginal.marginalCovariance(V(2))-.09*Matrix3::Identity()).cwiseAbs().maxCoeff();tests["old_node_marginalized"]=!estimate.exists(V(0));
 auto params=PreintegrationParams::MakeSharedU(9.80665);params->accelerometerCovariance=Matrix3::Identity()*.01;params->gyroscopeCovariance=Matrix3::Identity()*.000025;params->integrationCovariance=Matrix3::Identity()*1e-8;Bias bias(Vector3(.03,-.02,.04),Vector3(.01,-.02,.005));Pose3 st(Rot3::RzRyRx(.1,-.15,.8),Vector3(2,3,4));PreintegratedImuMeasurements pim(params,bias);for(int i=0;i<100;i++)pim.integrateMeasurement(st.rotation().unrotate(Vector3(0,0,9.80665))+bias.accelerometer(),bias.gyroscope(),.005);auto pred=pim.predict(NavState(st,Vector3::Zero()),bias);tests["stationary_nonzero_orientation_bias_position_error"]=(pred.position()-st.translation()).norm();tests["stationary_velocity_error"]=pred.v().norm();tests["stationary_preint_P_min"]=Eigen::SelfAdjointEigenSolver<Matrix>(pim.preintMeasCov()).eigenvalues().minCoeff();
 bool pass=tests["pass"]&&tests["Huber_fixed_cache_gradient_max"].get<double>()<1e-5&&tests["deep_clone_cost_interference"].get<double>()==0&&tests["marginal_mean_vs_batch_max"].get<double>()<1e-6&&tests["marginal_P_vs_analytic_max"].get<double>()<1e-7&&tests["old_node_marginalized"].get<bool>()&&tests["stationary_velocity_error"].get<double>()<1e-10;tests["all_pass"]=pass;std::ofstream(argv[1])<<tests.dump(2);return pass?0:2;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
